DO $repair$ DECLARE v_oid oid; v_def text; v_old text := 'WHERE user_id = v_uid AND (expires_at IS NULL OR expires_at > now())'; v_new text; BEGIN FOR v_oid IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='ai_credit_spend' LOOP v_def:=pg_get_functiondef(v_oid); IF position(v_old in v_def)=0 THEN RAISE EXCEPTION 'Credit balance function changed; manual review required'; END IF; IF position('p_billing_environment text' in v_def)>0 THEN v_new:=v_old||' AND (source <> ''stripe_credit_pack'' OR environment = ''live'' OR (p_billing_environment = ''sandbox'' AND environment = ''sandbox''))'; ELSE v_new:=v_old||' AND (source <> ''stripe_credit_pack'' OR environment = ''live'')'; END IF; EXECUTE replace(v_def,v_old,v_new); END LOOP; END $repair$;